 "content": "def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        # Mark the trailing segment when a row's run from the left switches
        # from its leading color to the other color.
        if len(row) < 2:
            continue
        lead = row[0]
        i = 1
        while i < len(row) and row[i] == lead:
            i += 1
        if 0 < i < len(row):
            tail = row[i]
            if all(v == tail for v in row[i:]):
                row[i:] = [1] * (len(row) - i)
    return out
